    receive() external payable {}

    function run(address caller, address newOwner) public payable {
        require(caller != address(this), "caller must not be the test contract");
        require(newOwner != caller, "newOwner should differ from caller to avoid accidental success");

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        require(caller != ownerBefore, "caller must not be the current owner for this rule");

        bool reverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.owner() == ownerBefore);
    }
}

